24	/**
25	 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
26	 * sheet's claimed-total and due-total; an overdue claim's due has its {@link LateCharge} on top. A change takes a {@link #snapshot} before it alters
27	 * anything and calls {@link #recordChanges} once it has, which audits, after the change's own
28	 * lines, a ROLLUP line for each person whose figures moved (in the order they were added) and a
29	 * TOTALS line when the sheet's totals moved.
30	 */
31	@Service
32	public class RollupService {
33	
34	    /** A person's figures; a null due-total is n/a. */
35	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
36	        boolean sameAs(Figures other) {
37	            return other != null && claimed.compareTo(other.claimed) == 0 && Objects.equals(dueTotal, other.dueTotal);
38	        }
39	    }
40	
41	    /** The sheet's figures at a moment: each person's, by id in the order they were added, and the totals. */
42	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal) {}
43	
44	    private final PersonRepository people;
45	    private final ClaimRepository claims;
46	    private final RateRepository rates;
47	    private final SheetRepository sheets;
48	    private final Audit audit;
49	
50	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
51	            SheetRepository sheets, Audit audit) {
52	        this.people = people;
53	        this.claims = claims;
54	        this.rates = rates;
55	        this.sheets = sheets;
56	        this.audit = audit;
57	    }
58	
59	    /**
60	     * The sheet's figures now. Locks the sheet until the caller's transaction ends, so no other
61	     * change on the sheet moves the figures between this snapshot and the one after the change.
62	     */
63	    public Snapshot snapshot(String sheetId) {
64	        Sheet sheet = sheets.findForUpdate(sheetId).orElse(null);
65	        LocalDate today = sheet == null ? null : sheet.getToday();
66	        BigDecimal floor = sheet == null ? zero() : sheet.getFloor();
67	        BigDecimal latePct = sheet == null ? zero() : sheet.getLatePct();
68	        LocalDate policyDate = sheet == null ? null : sheet.getPolicyDate();
69	        Map<String, List<Rate>> ratesByGrade = new LinkedHashMap<>();
70	        for (Rate rate : rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId)) {
71	            ratesByGrade.computeIfAbsent(rate.getGrade(), g -> new ArrayList<>()).add(rate);
72	        }
73	        Map<Long, List<Claim>> claimsByPerson = new LinkedHashMap<>();
74	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
75	        Map<String, LocalDate> datesByNumber = Rounding.datesByNumber(all);
76	        for (Claim claim : all) {
77	            if (claim.getStatus().counts()) {
78	                claimsByPerson.computeIfAbsent(claim.getPersonId(), id -> new ArrayList<>()).add(claim);
79	            }
80	        }
81	        Map<Long, Figures> figures = new LinkedHashMap<>();
82	        BigDecimal claimedTotal = zero();
83	        BigDecimal dueTotal = zero();
84	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
85	            BigDecimal claimed = zero();
86	            BigDecimal due = zero();
87	            boolean fixed = false;
88	            for (Claim claim : claimsByPerson.getOrDefault(person.getId(), List.of())) {
89	                if (!person.counts(claim)) continue;
90	                claimed = claimed.add(claim.getAmount());
91	                if (claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)) fixed = true;
92	                String grade = person.gradeOn(claim.getDate());
93	                RoundingMode rounding = Rounding.of(Rounding.basisOf(claim, datesByNumber), policyDate, today);
94	                BigDecimal figure = LateCharge.withCharge(claim,
95	                        figureOf(claim, ratesByGrade.getOrDefault(grade, List.of()), floor, rounding), today,
96	                        latePct, rounding);
97	                // a due under a grade they had on its date but not today counts like a fixed one
98	                if (figure != null && today != null && !grade.equals(person.gradeOn(today))) fixed = true;
99	                // and so does a due under a rate that is not the one in force today
100	                if (figure != null && today != null && !Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()),
101	                        claim.getDate()).equals(Rate.inForce(ratesByGrade.getOrDefault(grade, List.of()), today))) fixed = true;
102	                if (figure != null) due = due.add(figure);
103	            }
104	            // As on screen: n/a when their grade has no rate today and none of the counted claims has a fixed
