384	  private readonly overdueByPerson = computed(() => {
385	    const today = this.session.today();
386	    const floor = cents(this.session.floor());
387	    const late = this.session.late();
388	    const by = new Map<number, Overdue>();
389	    for (const p of this.people()) {
