391	      const theirs = this.claimsOf(p.id);
392	      const overdue = theirs.filter((c) => this.counts(c) && isOverdue(c, today));
393	      by.set(p.id, { count: overdue.length, cents: overdue.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs)) ?? 0), 0) });
394	    }
395	    return by;
396	  });
