522	  /**
523	   * The sum of the dues of their claims that count, each already rounded to cents; null (n/a) when
524	   * their grade has no rate in force today and none of those claims has a due fixed when settled or bound by a statement,
525	   * nor a due under another grade they had on its date or under a rate not in force today.
526	   */
527	  private dueTotalCents(p: Person): number | null {
528	    const theirs = this.claimsOf(p.id);
529	    const counted = theirs.filter(this.counts);
530	    const pctOn = this.pctOnOf(p.id);
531	    const floor = cents(this.session.floor());
532	    const late = this.session.late();
533	    const gradeToday = this.gradeOf(p);
534	    const today = this.session.today();
535	    const otherRate = (c: Claim) => {
536	      const rates = this.ratesOf(gradeOn(p, c.date));
537	      return today !== null && rateOn(rates, c.date) !== rateOn(rates, today);
538	    };
539	    const fixed = (c: Claim) => c.settledDue !== null || (isBound(c) && c.statedDue !== null)
540	      || ((gradeOn(p, c.date) !== gradeToday || otherRate(c)) && claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs)) !== null);
541	    if (this.pctOf(gradeToday) === null && !counted.some(fixed)) return null;
542	    return counted.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs)) ?? 0), 0);
543	  }
