795	      return;
796	    }
797	    if (!this.grades.includes(grade)) {
798	      this.error.set('Choose a grade.');
799	      return;
800	    }
801	    const id = this.editingId();
802	    this.saving = true;
803	    try {
804	      if (id === null) {
805	        const added = await firstValueFrom(
806	          this.http.post<Person>(this.url(sheet), { name, grade }, { headers: this.headers() }),
807	        );
808	        if (this.session.sheetId() !== sheet) return;
809	        this.people.update((list) => [...list, added]);
810	      } else {
811	        const saved = await firstValueFrom(
812	          this.http.put<Person>(`${this.url(sheet)}/${id}`, { name, grade, gradeFrom, version: this.editingVersion }, { headers: this.headers() }),
813	        );
814	        if (this.session.sheetId() !== sheet) return;
815	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
816	      }
817	      this.reset();
818	    } catch (e) {
819	      if (e instanceof HttpErrorResponse && e.status === 412 && id !== null) {
820	        await this.showCurrent(sheet, id);
821	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
822	        this.error.set('That name is already in use on this sheet.');
823	      } else {
824	        this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
825	      }
826	    } finally {
827	      this.saving = false;
828	    }
829	  }
830	
831	  /**
832	   * Add a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person of
833	   * the name; one not on the sheet is added first with grade A. A refusal adds neither.
834	   */
835	  protected async quickAdd(): Promise<void> {
836	    if (this.quickAdding) return;
837	    this.quickError.set('');
838	    const sheet = this.session.sheetId();
839	    if (!sheet) return;
840	    const raw = this.quickForm.getRawValue();
841	    const name = raw.name.trim();
842	    const amount = raw.amount.trim();
843	    if (!name) {
844	      this.quickError.set('Enter a name.');
845	      return;
846	    }
847	    if (!/^\d{1,12}(\.\d{1,2})?$/.test(amount)) {
848	      this.quickError.set('Enter an amount of 0.00 or more, with at most two decimals.');
849	      return;
850	    }
851	    this.quickAdding = true;
852	    try {
853	      const done = await firstValueFrom(
854	        this.http.post<QuickAdded>(`/api/sheets/${encodeURIComponent(sheet)}/quick-add`, { name, amount }, { headers: this.headers() }),
855	      );
856	      if (this.session.sheetId() !== sheet) return;
857	      if (done.added) this.people.update((list) => [...list.filter((p) => p.id !== done.person.id), done.person]);
858	      this.claimSaved(done.claim);
859	      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
860	    } catch (e) {
861	      if (this.session.sheetId() !== sheet) return;
862	      this.quickError.set(
863	        e instanceof HttpErrorResponse && e.status === 423
864	          ? 'No claim dated inside a closed period can be changed.'
865	          : e instanceof HttpErrorResponse && e.status === 422
866	          ? RETIRED
867	          : e instanceof HttpErrorResponse && e.status === 409
868	          ? 'That name is already in use on this sheet.'
869	          : 'Could not quick-add that claim.',
870	      );
871	    } finally {
872	      this.quickAdding = false;
873	    }
874	  }
875	
876	  /** After a save refused as made from an old version: refuse it, and show the person as now stored. */
877	  private async showCurrent(sheet: string, id: number): Promise<void> {
878	    this.error.set('Someone else saved this person meanwhile; it now shows their values.');
879	    try {
880	      const list = await firstValueFrom(this.http.get<Person[]>(this.url(sheet), { headers: this.headers() }));
881	      if (this.session.sheetId() !== sheet) return;
882	      this.people.set(list);
883	      const current = list.find((p) => p.id === id);
884	      if (current && this.editingId() === id) {
885	        this.editingVersion = current.version;
886	        this.form.setValue({ name: current.name, grade: this.gradeOf(current), gradeFrom: '' }, { emitEvent: false });
887	      }
888	    } catch {
889	      // the error already shown stands
890	    }
891	  }
892	}
