1	import { HttpClient } from '@angular/common/http';
2	import { Component, effect, inject, signal } from '@angular/core';
3	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
4	import { firstValueFrom } from 'rxjs';
5	import { Session } from '../../core/session';
6	
7	/** A role a user name can be given; any name not given one is a clerk. */
8	export const ROLES = ['clerk', 'steward'];
9	
10	/** The grades a person can have; each can have its own terms. */
11	export const GRADES = ['A', 'B', 'C'] as const;
12	type Grade = (typeof GRADES)[number];
13	
14	/** A real calendar date written yyyy-mm-dd. */
15	function isDate(value: string): boolean {
16	  const at = Date.parse(`${value}T00:00:00Z`);
17	  return /^\d{4}-\d{2}-\d{2}$/.test(value) && !Number.isNaN(at) && new Date(at).toISOString().slice(0, 10) === value;
18	}
19	
20	interface RoleView {
21	  user: string;
22	  role: string;
23	}
24	
25	interface SettingsView {
26	  /** The highest due a clerk can settle, two decimals; null when there is no limit. */
27	  clerkLimit: string | null;
28	  /** The least a claim's live due can be, two decimals. */
29	  floor: string;
30	  /** The days after its date by which a claim is due, for a grade without its own. */
31	  terms: number;
32	  /** The terms set for each grade that has its own, by grade. */
33	  gradeTerms: Partial<Record<Grade, number>>;
34	  /** The percent an overdue claim's due gains of its figure for every full 30 days overdue, two decimals. */
35	  latePct: string;
36	  /** Before it a claim's live figures round half up, else half to even (yyyy-mm-dd); null when blank: the sheet's today. */
37	  policyDate: string | null;
38	  /** From it (yyyy-mm-dd), a claim opened is numbered within its period; null when blank: off. */
39	  periodNumberingFrom: string | null;
40	  roles: RoleView[];
41	}
42	
43	// The sheet's settings: the clerk limit (blank: no limit), the floor of a claim's live due, the terms
44	// (the days after its date by which a claim is due, fixed when it is added), the terms of each grade (overriding the
45	// sheet's for a person of that grade on the claim's date), the late percent (charged on an overdue claim's
46	// figure for every full 30 days overdue), the policy date (blank: the sheet's today; a claim dated before it
47	// rounds half up, else half to even), the period numbering from (blank: off; while the sheet's today is on or after it,
48	// a claim opened is numbered within its period), and the role given to each user name. Saving stores the settings whose
49	// field was changed since the last save; clearing the clerk limit, the policy date or the period numbering from (Delete or
50	// Backspace) counts as a change even when it was already blank.
51	@Component({
52	  selector: 'app-settings',
53	  imports: [ReactiveFormsModule],
54	  template: `
55	    <section aria-labelledby="settings-heading">
56	      <h2 id="settings-heading">Settings</h2>
57	      <form [formGroup]="form" (ngSubmit)="save()" aria-label="Settings">
