206	    if (this.submitting.has('save')) return;
207	    this.error.set('');
208	    const sheet = this.session.sheetId();
209	    if (!sheet) return;
210	    const { clerkLimit, floor, terms, latePct, policyDate, periodNumberingFrom } = this.form.controls;
211	    const value = clerkLimit.value.trim();
212	    const floorValue = floor.value.trim();
213	    const termsValue = terms.value.trim();
214	    const latePctValue = latePct.value.trim();
215	    const policyDateValue = policyDate.value.trim();
