329	        [...list.filter((r) => r.user !== saved.user), saved].sort((a, b) => (a.user < b.user ? -1 : 1)),
330	      );
331	    } catch {
332	      if (this.session.sheetId() === sheet) this.roleError.set('Could not set that role.');
